-- Session 6 dataset: Complex queries (subqueries + combining results)
-- Theme: everyday online shop
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS session6_complex_queries;
CREATE DATABASE session6_complex_queries CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE session6_complex_queries;

DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS archived_customers;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS products;

CREATE TABLE customers (
    customer_id INT PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    city VARCHAR(50) NOT NULL,
    membership_level VARCHAR(20) NOT NULL,
    signup_date DATE NOT NULL,
    email VARCHAR(120) NOT NULL
);

CREATE TABLE archived_customers (
    archived_customer_id INT PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    city VARCHAR(50) NOT NULL,
    membership_level VARCHAR(20) NOT NULL,
    archived_date DATE NOT NULL,
    email VARCHAR(120) NOT NULL
);

CREATE TABLE products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(120) NOT NULL,
    category VARCHAR(40) NOT NULL,
    price DECIMAL(10,2) NOT NULL,
    stock_qty INT NOT NULL,
    added_date DATE NOT NULL
);

CREATE TABLE orders (
    order_id INT PRIMARY KEY,
    customer_id INT NOT NULL,
    order_date DATE NOT NULL,
    total_amount DECIMAL(10,2) NOT NULL,
    status VARCHAR(20) NOT NULL,
    payment_method VARCHAR(20) NOT NULL
);

CREATE INDEX idx_orders_customer_id ON orders(customer_id);
CREATE INDEX idx_orders_status ON orders(status);
CREATE INDEX idx_products_category ON products(category);
CREATE INDEX idx_customers_city ON customers(city);

